.summon-btn .sb-cost .icon{font-size:11px}
.pity-line{font-size:6.5px;color:#6c7e9a;letter-spacing:.05em;text-align:center;margin-top:6px}
.gacha-note{font-size:8px;color:#6c7e9a;line-height:1.6;padding:9px 0 0;border-top:1px solid rgba(255,255,255,.06);margin-top:11px}

/* gacha results */
.gacha-results{position:absolute;inset:0;z-index:5;display:flex;flex-direction:column;background:radial-gradient(ellipse at 50% 32%,#1a2747,#05080f 72%);animation:resultsIn .4s ease}
@keyframes resultsIn{from{opacity:0}}
.result-rays{
  position:absolute;width:160%;aspect-ratio:1;left:50%;top:44%;translate:-50% -50%;opacity:.6;
  background:conic-gradient(from 0deg,transparent 0 12deg,rgba(255,231,170,.16) 13deg,transparent 15deg 40deg,rgba(255,231,170,.1) 41deg,transparent 43deg 76deg,rgba(255,231,170,.14) 77deg,transparent 79deg 118deg,rgba(255,231,170,.09) 119deg,transparent 121deg 160deg,rgba(255,231,170,.13) 161deg,transparent 163deg 210deg,rgba(255,231,170,.1) 211deg,transparent 213deg);
  mask-image:radial-gradient(circle,#000 8%,transparent 62%);animation:rays 60s linear infinite;
}
.results-head{position:relative;z-index:2;text-align:center;padding:22px 20px 10px;flex-shrink:0}
.results-head span{font-size:7px;letter-spacing:.35em;color:#a98c55;font-weight:800}
.results-head h3{font-family:var(--display);font-size:24px;font-weight:500;letter-spacing:.1em;color:#f5e7c9;margin-top:3px}
.results-head p{font-size:8px;color:#7d8ba0;margin-top:4px}
.result-grid{
  position:relative;z-index:2;flex:1;min-height:0;overflow-y:auto;
  display:grid;grid-template-columns:repeat(5,1fr);gap:9px;padding:12px 34px;align-content:center;
  max-width:850px;margin:0 auto;width:100%;
}
.result-card{
  position:relative;border-radius:6px;overflow:hidden;aspect-ratio:.78;
  background:linear-gradient(170deg,#1a2438,#0a0f1b);
  border:1px solid rgba(255,255,255,.11);
  display:flex;flex-direction:column;
  opacity:0;transform:translateY(18px) rotateY(25deg);
  animation:cardReveal .55s cubic-bezier(.2,.8,.3,1) forwards;
  transition:transform .2s, border-color .2s;
}
@keyframes cardReveal{to{opacity:1;transform:none}}
.result-card:hover{transform:translateY(-4px);border-color:rgba(244,211,138,.45)}
.result-card .rc-art{flex:1;position:relative;overflow:hidden;background:radial-gradient(circle at 50% 72%,rgba(110,150,220,.2),transparent 65%)}
.result-card .rc-art img{width:100%;height:100%;object-fit:contain;position:relative;z-index:1;filter:drop-shadow(0 8px 14px rgba(0,0,0,.45))}
.result-card .rc-art:before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(5,8,15,.9))}
.result-card .rc-info{position:relative;z-index:2;padding:5px 7px 7px;margin-top:-18px}
.result-card .rc-stars{font-size:7.5px;letter-spacing:.13em;color:var(--gold)}
.result-card .rc-name{font-size:7.5px;font-weight:700;line-height:1.25;color:#eaf2ff;margin-top:1px}
.result-card .rc-new{
  position:absolute;top:5px;left:5px;z-index:3;font-size:5.5px;letter-spacing:.16em;font-weight:800;
  color:#1b270b;background:linear-gradient(140deg,#c8ffa3,#77e6a8);padding:2px 4px;border-radius:1px;
}
.result-card.dup .rc-art img{filter:grayscale(.55) brightness(.8)}
.result-card.rarity5{border-color:rgba(255,203,102,.6);box-shadow:0 0 24px rgba(255,203,102,.15), inset 0 0 30px rgba(255,203,102,.05)}
.result-card.rarity5:before{
  content:'';position:absolute;inset:0;z-index:1;pointer-events:none;
  background:linear-gradient(160deg,rgba(255,214,130,.22),transparent 45%);
}
.result-card.rarity4{border-color:rgba(177,140,255,.45)}
.result-card.rarity4:before{content:'';position:absolute;inset:0;z-index:1;pointer-events:none;background:linear-gradient(160deg,rgba(177,140,255,.14),transparent 45%)}
.result-card.rarity5 .rc-stars{color:#ffd166;text-shadow:0 0 8px rgba(255,209,102,.5)}
.result-card.rarity4 .rc-stars{color:#c7aaff}
.result-foot{position:relative;z-index:2;display:flex;align-items:center;justify-content:center;gap:16px;padding:14px 20px 20px;flex-shrink:0}
.result-shards{font-size:8px;color:#8d9cb4;display:flex;align-items:center;gap:5px}
.result-shards b{color:var(--violet);font-size:11px}
.results-actions{display:flex;gap:7px}

/* character / collection modal */
.char-body{display:grid;grid-template-columns:300px 1fr;gap:22px;align-items:start}
.char-preview{
  position:relative;border:1px solid rgba(255,255,255,.09);border-radius:7px;overflow:hidden;
  background:radial-gradient(ellipse at 50% 74%,rgba(91,137,210,.22),transparent 62%),linear-gradient(180deg,rgba(255,255,255,.025),rgba(0,0,0,.2));
  padding:14px;text-align:center;
}
.char-preview img{width:100%;aspect-ratio:1;object-fit:contain;filter:drop-shadow(0 16px 24px rgba(0,0,0,.5))}
.char-preview .cp-set{font-size:7px;letter-spacing:.22em;color:var(--gold);font-weight:800;text-transform:uppercase}
.char-preview .cp-name{font-family:var(--display);font-size:18px;font-weight:500;margin-top:2px;letter-spacing:.04em}
.char-stats{margin-top:12px;display:flex;flex-direction:column;gap:5px;text-align:left}
.char-stat{display:flex;align-items:center;justify-content:space-between;font-size:8px;color:#8497b4;border-bottom:1px solid rgba(255,255,255,.05);padding:4px 2px}
.char-stat b{color:#dbe7f7;font-size:10px;font-weight:700;font-variant-numeric:tabular-nums}
.char-equip-note{font-size:7.5px;color:#6c7e9b;line-height:1.5;margin-top:11px;text-align:left;border-top:1px dashed rgba(255,255,255,.08);padding-top:8px}
.collection-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}
.collection-head h3{font-size:10px;letter-spacing:.2em;text-transform:uppercase;color:#c4d3e8;font-weight:800}
.collection-head span{font-size:8px;color:#7184a2}
.avatar-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}
.avatar-tile{
  position:relative;border:1px solid rgba(255,255,255,.09);border-radius:5px;overflow:hidden;
  background:linear-gradient(165deg,rgba(24,36,61,.7),rgba(7,11,20,.8));
  cursor:pointer;transition:.2s;aspect-ratio:.8;
}
.avatar-tile img{width:100%;height:82%;object-fit:contain;display:block;margin-top:2px;filter:drop-shadow(0 5px 8px rgba(0,0,0,.4))}
.avatar-tile .at-info{position:absolute;bottom:0;left:0;right:0;padding:3px 4px 4px;background:linear-gradient(180deg,transparent,rgba(4,7,14,.92) 36%)}
.avatar-tile .at-info b{display:block;font-size:5.8px;line-height:1.2;font-weight:700;color:#d5e2f4;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.avatar-tile .at-info span{display:block;font-size:5px;color:var(--gold);letter-spacing:.08em;margin-top:1px}
.avatar-tile:hover{border-color:rgba(244,211,138,.4);transform:translateY(-2px)}
.avatar-tile.equipped{border-color:rgba(244,211,138,.7);box-shadow:0 0 16px rgba(244,211,138,.15)}
.avatar-tile.equipped:after{content:'EQUIPPED';position:absolute;top:3px;left:3px;font-size:4.5px;letter-spacing:.1em;background:var(--gold);color:#231805;padding:1px 3px;border-radius:1px;font-weight:800}
.avatar-tile.locked{filter:grayscale(.9) brightness(.6);cursor:default}
.avatar-tile.locked:hover{transform:none;border-color:rgba(255,255,255,.09)}
.avatar-tile .at-rarity{position:absolute;top:3px;right:3px;font-size:5.5px;letter-spacing:.05em;color:var(--gold);text-shadow:0 1px 2px #000}
.avatar-tile.locked .at-rarity{display:none}
.collection-empty{grid-column:1/-1;padding:28px;text-align:center;font-size:9px;color:#677a99;line-height:1.7;border:1px dashed rgba(255,255,255,.1);border-radius:6px}

/* settings / guide */
.settings-body{display:flex;flex-direction:column;gap:13px;max-width:600px;margin:0 auto}
.setting-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:9px 2px;border-bottom:1px solid rgba(255,255,255,.05)}
.setting-row label{font-size:10px;font-weight:600;color:#cfdbeb;display:block}
.setting-row small{display:block;font-size:7.5px;color:#6e809d;margin-top:2px}
.toggle{width:38px;height:20px;border-radius:20px;background:rgba(255,255,255,.12);position:relative;border:1px solid rgba(255,255,255,.12);transition:.2s;flex-shrink:0}
.toggle:after{content:'';position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:#8a9bb4;transition:.2s}
.toggle.on{background:rgba(244,211,138,.25);border-color:rgba(244,211,138,.5)}
.toggle.on:after{left:20px;background:var(--gold);box-shadow:0 0 8px rgba(244,211,138,.6)}
.select-pill{display:flex;gap:3px;padding:2px;border-radius:4px;background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.1)}
.select-pill button{padding:5px 9px;border-radius:2px;font-size:7px;letter-spacing:.1em;font-weight:800;color:#7184a3;transition:.15s}
.select-pill button.active{background:rgba(244,211,138,.15);color:var(--gold)}
.danger-btn{font-size:8px;letter-spacing:.12em;font-weight:800;color:#ff98a2;border:1px solid rgba(255,106,120,.3);padding:7px 12px;border-radius:3px;background:rgba(255,106,120,.05)}
.danger-btn:hover{background:rgba(255,106,120,.12)}
.guide-body{display:grid;grid-template-columns:1fr 1fr;gap:10px;max-width:700px;margin:0 auto}
.guide-item{display:flex;gap:10px;padding:11px;border:1px solid rgba(255,255,255,.07);border-radius:5px;background:rgba(255,255,255,.025)}
.guide-item .gi-icon{width:30px;height:30px;flex-shrink:0;border-radius:4px;display:flex;align-items:center;justify-content:center;background:rgba(115,230,255,.1);border:1px solid rgba(115,230,255,.2);font-size:13px}
.guide-item h4{font-size:9.5px;font-weight:700;color:#d9e5f5;margin-bottom:2px}
.guide-item p{font-size:8px;line-height:1.55;color:#7b8daa}
.guide-item p b{color:#d8c188}
.guide-tip{margin-top:13px;padding:10px;border-left:2px solid var(--gold);background:rgba(244,211,138,.05);font-size:8px;line-height:1.6;color:#a99b7c}

/* dialog modal */
.dialog-card{width:min(520px,94vw);max-height:70vh}
.dialog-body{padding:18px 24px 22px;overflow-y:auto}
.dialog-speaker{display:flex;gap:11px;align-items:center;margin-bottom:13px}
.dialog-avatar{width:52px;height:52px;border-radius:50%;border:1px solid rgba(244,211,138,.35);background:radial-gradient(circle at 50% 35%,#4b3a2a,#17110b);display:flex;align-items:center;justify-content:center;font-size:22px}
.dialog-speaker h3{font-family:var(--display);font-size:16px;font-weight:500;letter-spacing:.04em}
.dialog-speaker span{font-size:7px;letter-spacing:.18em;color:var(--gold);text-transform:uppercase;font-weight:700}
.dialog-text{font-size:10px;line-height:1.85;color:#aebdd2;background:rgba(0,0,0,.2);border:1px solid rgba(255,255,255,.06);border-radius:5px;padding:12px 14px;min-height:80px}
.dialog-options{display:flex;flex-direction:column;gap:6px;margin-top:12px}
.dialog-option{
  display:flex;align-items:center;justify-content:space-between;gap:10px;
  padding:9px 13px;border-radius:4px;border:1px solid rgba(255,255,255,.09);background:rgba(255,255,255,.03);
  font-size:9px;color:#b8c7dc;text-align:left;transition:.2s;
}
.dialog-option:hover{border-color:rgba(244,211,138,.35);background:rgba(244,211,138,.06);color:#f0e6cf;transform:translateX(2px)}
.dialog-option small{font-size:7px;color:#6c7e9b;letter-spacing:.08em}
.dialog-option .do-cost{font-size:8px;color:var(--gold);font-weight:800;white-space:nowrap}

/* responsive */
@media(max-width:980px){
  #party-frame{display:none}
  #chat-feed{width:255px;max-height:150px}
  #chat-lines{height:105px}
  #quest-tracker{width:218px}
  .mission-body{grid-template-columns:1fr}
  .mission-side{max-width:320px}
  .char-body{grid-template-columns:240px 1fr}
  .avatar-grid{grid-template-columns:repeat(4,1fr)}
  .result-grid{grid-template-columns:repeat(4,1fr);padding:12px 22px}
  .gacha-stage{grid-template-columns:1fr .8fr}
  .banner-visual{min-height:240px}
}
@media(max-width:760px){
  #zone-info{display:none}
  #player-panel{min-width:0;width:min(56vw,270px)}
  #minimap-wrap{width:132px;padding:5px}
  #minimap{width:122px;height:122px}
  .minimap-foot{display:none}
  .top-actions{gap:4px}
  .icon-btn{width:29px;height:29px}
  .icon-btn svg{width:14px;height:14px}
  #quest-tracker{top:calc(196px + var(--safe-top));width:190px;padding:8px 10px}
  #quest-tracker .tracker-reward{display:none}
  #chat-feed{display:none}
  #hint-strip{display:none}
  #skill-dock{display:none}
  #joystick-zone{display:flex}
  #mobile-actions{display:flex}
  #hud-bottom{justify-content:flex-end}
  #btn-guide{display:none}
  #target-frame{top:calc(64px + var(--safe-top));min-width:240px}
  #boss-frame{top:calc(62px + var(--safe-top));width:90vw}
  .modal-layer{padding:8px}
  .modal-card{max-height:94vh;width:96vw}
  .modal-head{padding:14px 16px 11px}
  .modal-head h2{font-size:20px}
  .modal-head p{display:none}
  .modal-body{padding:13px 15px 16px}
  .modal-foot{padding:10px 15px 13px}
  .mission-side{max-width:none}
  .char-body{grid-template-columns:1fr}
  .char-preview{display:none}
  .avatar-grid{grid-template-columns:repeat(4,1fr)}
  .gacha-card{height:94vh}
  .banner-tabs{padding:0 10px;overflow-x:auto}
  .banner-tab{padding:9px 10px;font-size:7.5px;white-space:nowrap}
  .gacha-stage{grid-template-columns:1fr;grid-template-rows:1.15fr .85fr;overflow-y:auto}
  .banner-visual{min-height:200px}
  .banner-hero{width:min(62%,250px)}
  .banner-nameplate{left:16px;bottom:14px}
  .banner-nameplate h3{font-size:20px}
  .banner-nameplate p{display:none}
  .banner-side{padding:13px 15px;border-left:0;border-top:1px solid rgba(255,255,255,.07)}
  .banner-side h4,.featured-list{display:none}
  .rates-row{margin-bottom:8px;padding-top:0;border-top:0}
  .ticket-callout{padding:6px;margin-bottom:6px}
  .summon-buttons{flex-direction:row}
  .summon-btn{padding:8px}
  .summon-btn .sb-main small{display:none}
  .gacha-note{display:none}
  .result-grid{grid-template-columns:repeat(3,1fr);gap:6px;padding:8px 12px}
  .results-head{padding:12px 12px 6px}
  .results-head h3{font-size:18px}
  .result-foot{flex-wrap:wrap;gap:8px;padding:8px 12px 12px}
  .guide-body{grid-template-columns:1fr}
  .result-card .rc-name{font-size:6.5px}
  .toast{font-size:8.5px;padding:8px 12px}
  #toasts{top:calc(57px + var(--safe-top))}
}
@media(max-width:480px){
  #player-panel{width:56vw;padding:6px 8px 6px 6px;gap:7px}
  .portrait-wrap{width:42px;height:42px}
  .player-name-row strong{font-size:10px}
  .class-chip{font-size:6px}
  .stat-bar{height:7px}
  .stat-bar.xp{height:3px}
  #minimap-wrap{width:104px}
  #minimap{width:94px;height:94px}
  #quest-tracker{width:166px;font-size:7px;top:calc(168px + var(--safe-top))}
  .tracker-head h3{font-size:7.5px}
  #tracker-list li b{font-size:7.5px}
  .tracker-head button{font-size:6px}
  #target-frame{top:calc(56px + var(--safe-top));min-width:200px;padding:5px 10px 5px 5px}
  .target-portrait{width:30px;height:30px;font-size:14px}
  .target-head strong{font-size:9px}
  .action-btn{width:64px;height:64px;font-size:25px}
  .action-btn.small{width:44px;height:44px;font-size:7px}
  #mobile-actions{gap:8px;right:calc(14px + var(--safe-right))}
  #joystick-zone{left:calc(18px + var(--safe-left))}
  #joystick-base{width:100px;height:100px}
  #joystick-knob{width:40px;height:40px}
  .avatar-grid{grid-template-columns:repeat(3,1fr)}
  .mission-card{padding:9px 10px;gap:9px}
  .mission-icon{width:30px;height:30px;font-size:13px}
  .mission-main h4{font-size:9.5px}
  .mission-main p{font-size:7.5px}
}
@media(orientation:landscape) and (max-height:500px) and (pointer:coarse){
  #quest-tracker{display:none}
  #player-panel{transform:scale(.86);transform-origin:top left}
  #minimap-wrap{transform:scale(.8);transform-origin:top right}
  #joystick-base{width:94px;height:94px}
  #mobile-actions{bottom:0}
  #skill-dock{transform:scale(.88);transform-origin:bottom center}
}
@media(prefers-reduced-motion:reduce){
  *,*:before,*:after{animation-duration:.001s !important;animation-iteration-count:1 !important;transition-duration:.001s !important}
}

files.patch:
Index: src/style.css
===================================================================
--- src/style.css
+++ src/style.css
@@ -738,4 +738,456 @@
 #fade{position:absolute;inset:0;z-index:150;background:#03060d;opacity:0;pointer-events:none;transition:opacity .55s ease}
 #fade.active{opacity:1;pointer-events:auto}
 #rotate-hint{display:none;position:absolute;left:0;right:0;bottom:18px;z-index:120;text-align:center;font-size:9px;letter-spacing:.08em;color:#8395b1}
 #rotate-hint span{display:inline-block;margin-right:6px;animation:spinPulse 2.4s infinite}
+
+/* ══════════════ MODALS ══════════════ */
+#modal-root{position:absolute;inset:0;z-index:110;pointer-events:none}
+.modal-layer{
+  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;padding:20px;
+  background:rgba(3,6,14,.68);backdrop-filter:blur(7px) saturate(.9);-webkit-backdrop-filter:blur(7px);
+  pointer-events:auto;animation:modalBg .3s ease;overflow:hidden;
+}
+@keyframes modalBg{from{opacity:0}}
+.modal-card{
+  position:relative;width:min(960px,96vw);max-height:min(88vh,860px);display:flex;flex-direction:column;
+  clip-path:polygon(0 0,calc(100% - 24px) 0,100% 24px,100% 100%,24px 100%,0 calc(100% - 24px));
+  animation:modalIn .4s cubic-bezier(.2,.85,.3,1);
+}
+@keyframes modalIn{from{opacity:0;transform:translateY(18px) scale(.985)}to{opacity:1;transform:none}}
+.modal-card:before{
+  content:'';position:absolute;inset:0;pointer-events:none;z-index:0;
+  background:radial-gradient(ellipse at 12% 0%,rgba(88,130,200,.14),transparent 46%);
+}
+.modal-head{
+  position:relative;z-index:2;display:flex;align-items:flex-start;justify-content:space-between;
+  padding:20px 26px 14px;border-bottom:1px solid rgba(255,255,255,.07);flex-shrink:0;
+}
+.modal-head h2{font-family:var(--display);font-size:25px;font-weight:500;letter-spacing:.025em;margin-top:4px}
+.modal-head h2 em{font-style:normal;color:var(--gold)}
+.modal-head p{font-size:9px;color:#788aa8;letter-spacing:.03em;margin-top:3px;max-width:520px;line-height:1.6}
+.modal-close{
+  width:30px;height:30px;border-radius:4px;border:1px solid rgba(255,255,255,.14);
+  display:flex;align-items:center;justify-content:center;color:#8d9fba;font-size:15px;
+  transition:.2s;flex-shrink:0;
+}
+.modal-close:hover{color:#fff;border-color:rgba(255,106,120,.5);background:rgba(255,106,120,.1);transform:rotate(90deg)}
+.modal-body{position:relative;z-index:1;padding:18px 26px 22px;overflow-y:auto;min-height:0}
+.modal-foot{
+  position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:12px;
+  padding:12px 26px 16px;border-top:1px solid rgba(255,255,255,.06);flex-shrink:0;flex-wrap:wrap;
+}
+
+.currency-row{display:flex;gap:7px;align-items:center}
+.currency{
+  display:flex;align-items:center;gap:5px;padding:4px 9px;border-radius:3px;
+  background:rgba(0,0,0,.35);border:1px solid rgba(255,255,255,.1);
+  font-size:9px;font-weight:700;color:#d4e2f5;
+}
+.currency .cur-icon{font-size:11px}
+.currency.gem .cur-icon{color:var(--cyan)}
+.currency.ticket .cur-icon{color:var(--gold)}
+.currency.shard .cur-icon{color:var(--violet)}
+
+/* mission modal */
+.mission-body{display:grid;grid-template-columns:1fr 250px;gap:20px;align-items:start}
+.mission-list{display:flex;flex-direction:column;gap:9px}
+.mission-card{
+  position:relative;display:flex;gap:13px;align-items:center;padding:13px 15px;border-radius:6px;
+  background:linear-gradient(120deg,rgba(255,255,255,.04),rgba(255,255,255,.015));
+  border:1px solid rgba(255,255,255,.08);transition:.2s;
